const inputData = $input.item.json;
const data = inputData.body || inputData;
const destination = data.destination || (data.preference_snapshot && data.preference_snapshot.destination) || '東京';
const days = Number(data.days || (data.preference_snapshot && data.preference_snapshot.total_days) || 3);
const prefs = data.preference_snapshot || {};
const pace = prefs.pace || 'moderate';
const budget = prefs.budget_level || 'standard';
const accommodation = prefs.accommodation_strategy || 'single_hotel';
const transit = prefs.transit_mode || 'public_transit';
const interests = Array.isArray(prefs.interests) ? prefs.interests : ['gourmet', 'cultural'];
const eventNote = prefs.event_note || '';

const baseRules = [
  '你是 Atrip 頂級 AI 自由行旅遊管家。擅長規劃真實可行、具備地理精確度、深度在地化的行程。',
  '必須嚴格輸出純 JSON 格式，不得包含 markdown。',
  '所有 location_name 必須是真實世界具體的景點、歷史地標、餐廳或商圈全名（嚴禁使用泛稱）。',
  '每個活動皆須包含真實經緯度 (lat/lng)、停留時間 (duration_minutes) 與交通轉乘指引 (transit_to_next)。',
  '每日活動按照同一個市區分區安排，避免折返跑。'
].join('\n');

const directives = [];
if (accommodation === 'single_hotel') {
  directives.push('【住宿約束】以推薦飯店為固定 Basecamp，每日動線以飯店為圓心，中途嚴禁更換住宿。');
} else {
  directives.push('【換宿約束】允許分區換宿。更換飯店當日，上午安排行李寄存，下午安排 Check-in。');
}

if (transit === 'public_transit') {
  directives.push('【交通模式】優先搭乘地鐵、捷運或鐵路。transit_to_next 具體指明路線代碼、方向與出口。');
} else {
  directives.push('【交通模式】自駕為主，估算自駕時間並提示周邊停車方便度。');
}

if (interests.includes('gourmet')) directives.push('【美食強化】每日午晚餐推薦高評價特色餐飲，避免觀光客陷阱。');
if (interests.includes('shopping')) directives.push('【購物排程】安排 1-2 個核心商圈，預留充裕逛街時間。');
if (interests.includes('sports')) directives.push('【運動賽事】優先安排知名體育場館或賽事活動。');
if (eventNote && eventNote.trim()) {
  directives.push(`【時間錨點】活動：${eventNote.trim().slice(0, 100)}，當日周邊活動以此為軸心安排。`);
}

const formatSchema = {
  meta: { trip_title: `${destination} ${days} 天深度自由行`, destination, total_days: days, currency: 'TWD', budget_level: budget, pace },
  daily_itinerary: [{
    day_number: 1, date_label: '第 1 天 · 區域核心探索', summary: '探索核心地標與排隊名店',
    activities: [{
      id: 'act-d1-1', time_slot: '10:00 - 12:30', location_name: '真實景點全名', category: 'sightseeing', duration_minutes: 150,
      description: '具體描繪該景點特色與遊覽重點。', coordinates: { lat: 35.7147, lng: 139.7967 }, cost_estimate: 500,
      tips: '實用避坑技巧與最佳時段。',
      transit_to_next: { mode: 'subway', duration_minutes: 15, route_name: '地鐵/巴士路線', instructions: '從 A 站搭乘 X 線至 B 站' }
    }]
  }],
  transit_overview: { primary_mode: 'public_transit', summary: '主要交通工具概況', recommendations: ['推薦交通票券', '乘車秘訣'] },
  recommendations: { dining: ['必吃名店 1', '必吃名店 2'], notes: '注意事項' },
  packing_list: [
    { category: 'essentials', item_name: '護照正本（效期6個月以上）與入境申報碼', is_checked: false, notes: '隨身攜帶勿托運' },
    { category: 'essentials', item_name: '海外高回饋雙幣信用卡與當地現鈔', is_checked: false, notes: '應急金流備用' },
    { category: 'clothing', item_name: '配合當地季節的透氣排汗衫與好走健步鞋', is_checked: false, notes: '每日萬步健走必備' },
    { category: 'clothing', item_name: '防風保暖外套或折疊雨傘', is_checked: false, notes: '因應早晚溫差與天氣' },
    { category: 'electronics', item_name: '大容量行動電源與該國專用規格轉接插頭', is_checked: false, notes: '行動電源需放隨身行李' },
    { category: 'electronics', item_name: '當地上網 eSIM / 實體 SIM 卡與快充線組', is_checked: false, notes: '出發前完成開通' },
    { category: 'toiletries', item_name: '個人常備用藥（止痛/胃腸藥/暈車藥）', is_checked: false, notes: '隨身備用' },
    { category: 'toiletries', item_name: '旅行分裝盥洗包、保濕乳液與防曬乳', is_checked: false, notes: '隨身攜帶需小於100ml' }
  ]
};

const assembledSystemPrompt = [
  '## Base System Rules', baseRules, '',
  '## Injected Directives', directives.join('\n'), '',
  '## Output JSON Schema Reference', JSON.stringify(formatSchema, null, 2)
].join('\n');

const userPrompt = `目的地：${destination}，天數：${days} 天，步調：${pace}。請為我產生完整 ${days} 天每天 3~4 個真實具體景點與美食，以及完整的 4 大類（重要證件與金流、季節衣物與配件、3C 數位與充電設備、隨身常備藥與盥洗）行李打包清單 JSON。`;

return [{
  json: {
    itineraryId: data.itineraryId,
    userId: data.userId,
    destination,
    days,
    assembledSystemPrompt,
    userPrompt,
    llmRequestBody: {
      model: 'openrouter/free',
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: assembledSystemPrompt },
        { role: 'user', content: userPrompt }
      ]
    }
  }
}];

const rawResponse = $input.item.json;
let content = '';
if (rawResponse.choices && rawResponse.choices[0] && rawResponse.choices[0].message) {
  content = rawResponse.choices[0].message.content;
} else if (typeof rawResponse === 'string') {
  content = rawResponse;
} else {
  content = JSON.stringify(rawResponse);
}

content = content.replace(/^\s*```json/i, '').replace(/```\s*$/i, '').trim();

let parsed = {};
try {
  parsed = JSON.parse(content);
} catch (e) {
  throw new Error('LLM output could not be parsed as JSON: ' + e.message);
}

// 1. 活動 UUID 注入
if (Array.isArray(parsed.daily_itinerary)) {
  parsed.daily_itinerary.forEach((day, dIdx) => {
    const dNum = day.day_number || dIdx + 1;
    if (Array.isArray(day.activities)) {
      day.activities.forEach((act, aIdx) => {
        if (!act.id || act.id.length < 5) {
          const rand = Math.random().toString(16).slice(2, 8);
          act.id = `act-d${dNum}-${aIdx + 1}-${rand}`;
        }
        if (act.coordinates) {
          act.coordinates.lat = Number(act.coordinates.lat) || 0;
          act.coordinates.lng = Number(act.coordinates.lng) || 0;
        }
        act.duration_minutes = Number(act.duration_minutes) || 60;
        act.cost_estimate = Number(act.cost_estimate) || 0;
      });
    }
  });
}

// 2. 4 大類智能行李清單標準化 (優先保留 LLM 客製化項目)
const validCategories = ['essentials', 'clothing', 'electronics', 'toiletries'];
const DEFAULT_FALLBACKS = {
  essentials: [
    { item_name: '護照正本（效期6個月以上）與入境申報單', notes: '隨身攜帶勿托運' },
    { item_name: '海外高回饋信用卡與當地貨幣現鈔', notes: '應急金流備用' }
  ],
  clothing: [
    { item_name: '舒適好走防滑健步鞋', notes: '每日萬步自由行必備' },
    { item_name: '防風保暖外套與換洗衣物', notes: '因應早晚溫差與氣候變化' }
  ],
  electronics: [
    { item_name: '大容量行動電源 (需隨身攜帶)', notes: '拍照與地圖導航必備，嚴禁托運' },
    { item_name: '萬國通用規格轉接插頭與多孔快充線組', notes: '充電必備' }
  ],
  toiletries: [
    { item_name: '個人常備藥（止痛/胃腸藥/暈車藥）', notes: '隨身備用' },
    { item_name: '旅行分裝便攜盥洗包與保濕防曬乳', notes: '隨身液體小於100ml' }
  ]
};

const normalizedList = [];
const categoryCounts = { essentials: 0, clothing: 0, electronics: 0, toiletries: 0 };

if (Array.isArray(parsed.packing_list)) {
  parsed.packing_list.forEach((item, idx) => {
    let cat = String(item.category || 'essentials').toLowerCase().trim();
    if (cat === 'essential' || cat === 'documents' || cat === 'document') cat = 'essentials';
    if (cat === 'clothes') cat = 'clothing';
    if (cat === 'electronic' || cat === 'tech' || cat === 'digital') cat = 'electronics';
    if (cat === 'toiletry' || cat === 'medicine' || cat === 'medical') cat = 'toiletries';
    if (!validCategories.includes(cat)) cat = 'essentials';

    const itemName = String(item.item_name || item.name || '').trim();
    if (!itemName) return;

    const rand = Math.random().toString(16).slice(2, 8);
    normalizedList.push({
      id: item.id || `pack-${cat}-${idx + 1}-${rand}`,
      category: cat,
      item_name: itemName,
      is_checked: Boolean(item.is_checked),
      notes: item.notes || '自由行專屬推薦'
    });
    categoryCounts[cat]++;
  });
}

// 補足不足 2 項之類別
validCategories.forEach(cat => {
  if (categoryCounts[cat] < 2) {
    const fbs = DEFAULT_FALLBACKS[cat] || [];
    fbs.forEach((fb, fbIdx) => {
      const isDuplicate = normalizedList.some(i => i.item_name.includes(fb.item_name.slice(0, 4)));
      if (!isDuplicate && normalizedList.filter(i => i.category === cat).length < 3) {
        const rand = Math.random().toString(16).slice(2, 8);
        normalizedList.push({
          id: `pack-${cat}-fb-${fbIdx + 1}-${rand}`,
          category: cat,
          item_name: fb.item_name,
          is_checked: false,
          notes: fb.notes
        });
      }
    });
  }
});

parsed.packing_list = normalizedList;

const meta = parsed.meta || {};
const title = meta.trip_title || `${meta.destination || '自由行'} ${meta.total_days || 3} 天探索旅程`;

const originalInput = $node['1. Receive Webhook'].json;
const webhookBody = originalInput.body || originalInput;
const itineraryId = webhookBody.itinerary_id || webhookBody.id;
const userId = webhookBody.user_id;

return [
  {
    json: {
      itineraryId,
      userId,
      title,
      destination: meta.destination || '旅遊目的地',
      status: 'completed',
      itinerary_data: parsed,
      updated_at: new Date().toISOString()
    }
  }
];
